 void LinkExcel(){if(!Allowed())return;using(var d=new SaveFileDialog{Filter="Excel macro-enabled workbook|*.xlsm|Excel workbook|*.xlsx",FileName="Beam-Summary.xlsm",OverwritePrompt=false}){if(d.ShowDialog(this)!=DialogResult.OK)return;var next=new ExcelLiveLink(d.FileName);try{string snapshot=next.ReadEstimate();bool restore=snapshot!=null;if(restore&&catalog!=null){var choice=MessageBox.Show(this,"This workbook contains a saved estimate.\nYes: load the workbook estimate.\nNo: replace its saved estimate with the current app estimate.\nCancel: leave the connection unchanged.","Choose estimate to use",MessageBoxButtons.YesNoCancel);if(choice==DialogResult.Cancel){next.Dispose();return;}restore=choice==DialogResult.Yes;}excelTimer.Stop();var previous=excelLink;excelLink=null;try{if(restore)OpenEstimateXml(snapshot);else if(catalog==null)throw new Exception("Load a DXF or choose a workbook with a saved estimate first.");}catch{excelLink=previous;throw;}if(previous!=null)previous.Dispose();excelLink=next;beams.EndEdit();Recalculate();SyncExcel();}catch{if(excelLink!=next)next.Dispose();throw;}}}
 void DisconnectExcel(){beams.EndEdit();Recalculate();excelTimer.Stop();if(excelLink!=null){try{SyncExcel();}catch(Exception ex){if(MessageBox.Show(this,"Excel save failed: "+ex.Message+"\nDisconnect without saving the latest changes to Excel? Save a separate estimate backup if needed.","Disconnect Excel",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;}}if(excelLink!=null)excelLink.Dispose();excelLink=null;excelStatus.Text="Excel: disconnected (workbook stays open)";}
 internal string[] WorksValidationIssues(){var issues=new List<string>();foreach(var input in inputs){if(input.Result==null)issues.Add("Beam "+input.Beam+": "+input.Error);if(input.Measures==null)issues.Add("Beam "+input.Beam+" concrete/formwork: "+input.MeasureError);if(input.Support!="Elevated"&&input.Earthworks==null)issues.Add("Beam "+input.Beam+" earthworks: "+input.EarthworkError);}foreach(var cut in WorksPlan().Where(a=>a.Choice==null))issues.Add("Beam "+cut.Entry.Beam+" / "+cut.Line.Part+": cut "+cut.Demand.Cut.ToString("0.###",CultureInfo.InvariantCulture)+"m cannot be allocated to the checked stock lengths; review splice settings.");return issues.ToArray();}
 public object[,] ExcelRows(List<StockAllocation> shared=null,bool requireValid=true){var all=shared==null?CommercialBars.Allocate(inputs,lengthProfile,stockLengths):shared.Where(a=>inputs.Contains(a.Entry)).ToList();if(requireValid&&all.Any(a=>a.Choice==null))throw new Exception("Purchase plan has unresolved cuts; review Commercial bars.");if(!requireValid)all=all.Where(a=>a.Choice!=null&&a.Entry.Result!=null&&a.Entry.Measures!=null&&(a.Entry.Support=="Elevated"||a.Entry.Earthworks!=null)).ToList();var rows=new List<object[]>();foreach(var i in inputs.Where(x=>x.Result!=null))foreach(var g in all.Where(a=>a.Entry==i).GroupBy(a=>new{a.Demand.Grade,a.Demand.Diameter})){double main=g.Where(a=>a.Line.Part!="Stirrups"&&a.Line.Part!="Side-face").Sum(a=>a.Net),ties=g.Where(a=>a.Line.Part=="Stirrups").Sum(a=>a.Net),sfr=g.Where(a=>a.Line.Part=="Side-face").Sum(a=>a.Net);rows.Add(new object[]{i.Description,i.Beam,i.ScheduleLabel,g.Key.Grade,g.Key.Diameter,main,ties,sfr,g.Sum(a=>a.Splice+a.Waste),g.Sum(a=>a.Purchase),Read(i.Length,"length"),int.Parse(i.Quantity)});}var result=new object[rows.Count,12];for(int r=0;r<rows.Count;r++)for(int c=0;c<12;c++)result[r,c]=rows[r][c];return result;}
 void SyncExcel(){if(excelLink==null)return;excelLink.Update(ExcelRows(),inputs.Any(i=>i.Result==null)?"PARTIAL - invalid entries excluded":"Purchase kg; allowance column includes computed splice + stock offcut",EstimateXml(),ConcreteExcelRows());savedState=State();excelStatus.Text="Excel synced "+DateTime.Now.ToString("HH:mm:ss")+" | "+excelLink.PathName;} static DataGridView Grid(){var g=new WorksDataGridView{AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,EnableHeadersVisualStyles=false,SelectionMode=DataGridViewSelectionMode.CellSelect,ColumnHeadersHeight=42,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells};g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(20,33,51);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",9,FontStyle.Bold);g.DefaultCellStyle.Padding=new Padding(4);g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(247,249,252);GridAppearance.Apply(g);return g;}
 static void Button(FlowLayoutPanel p,string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=30,FlatStyle=FlatStyle.Flat,BackColor=Color.White};b.Click+=(o,e)=>{try{action();}catch(Exception ex){MessageBox.Show(ex.Message,"Beam estimator",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};p.Controls.Add(b);}
 static NumericUpDown Number(FlowLayoutPanel p,string label,decimal min,decimal max,decimal value,int decimals){var box=new FlowLayoutPanel{Width=120,Height=58,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(3,0,3,0)};box.Controls.Add(new Label{Text=label,UseMnemonic=false,Width=120,Height=20});var n=new NumericUpDown{Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Increment=decimals==0?1:.25m,Width=114};box.Controls.Add(n);p.Controls.Add(box);return n;}
 static ComboBox Select(FlowLayoutPanel p,string label,string[] values){var box=new FlowLayoutPanel{Width=170,Height=58,FlowDirection=FlowDirection.TopDown,WrapContents=false};box.Controls.Add(new Label{Text=label,UseMnemonic=false,Width=170,Height=20});var c=new ComboBox{Width=165,DropDownStyle=ComboBoxStyle.DropDownList};c.Items.AddRange(values);c.SelectedIndex=0;box.Controls.Add(c);p.Controls.Add(box);return c;}
 bool Allowed(){if(AccessCodes.CanUseApp(2))return true;MessageBox.Show("Renew the eight-hour access to continue.");return false;}
 EstimateOptions Options(){return new EstimateOptions{LengthConfig=lengthProfile,GradeSmall=((SteelSelection)gradeSmall.SelectedItem).Grade,Grade=((SteelSelection)grade.SelectedItem).Grade,Fc=(double)concrete.SelectedItem,MainHook=mainHook.SelectedIndex==0?0:mainHook.SelectedIndex==1?90:180,Anchorage=anchorage.SelectedIndex,BondRatio=(double)bond.Value,Left=.25,Right=.25,Cover=(double)cover.Value,Hook=(double)hook.Value,Extra=(double)extra.Value,Waste=0,Offset=50};} bool ReplaceOkay(){beams.EndEdit();Recalculate();return inputs.Count==0||State()==savedState||MessageBox.Show(this,"Replace the current estimate entries? Save them first if needed.","Load schedule",MessageBoxButtons.OKCancel)==DialogResult.OK;}
 void Choose(){if(!Allowed()||!ReplaceOkay())return;using(var d=new OpenFileDialog{Filter="Beam schedule DXF (*.dxf)|*.dxf",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK){var files=d.FileNames.Select(path=>new[]{File.ReadAllText(path),Path.GetFileName(path)}).ToList();ValidateFiles(files,false);LoadCatalog(files[0][0],files[0][1]);foreach(var file in files.Skip(1))AppendCatalog(file[0],file[1]);}}
 void ChooseAdditional(){if(!Allowed())return;using(var d=new OpenFileDialog{Filter="Beam schedule DXF (*.dxf)|*.dxf",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK){var files=d.FileNames.Select(path=>new[]{File.ReadAllText(path),Path.GetFileName(path)}).ToList();ValidateFiles(files,true);foreach(var file in files)AppendCatalog(file[0],file[1]);}}
 public void LoadCatalog(string raw,string name){ManualBeamSchedule.Read(raw,name);filling=true;try{beams.Rows.Clear();sources.Clear();schedules.Clear();inputs.Clear();((DataGridViewComboBoxColumn)beams.Columns[1]).Items.Clear();((DataGridViewComboBoxColumn)beams.Columns[13]).Items.Clear();}finally{filling=false;}AppendCatalog(raw,name);savedState=State();}
 public void AppendCatalog(string raw,string name){if(sources.Any(s=>s.Raw==raw))return;var a=ManualBeamSchedule.Read(raw,name);CheckUniqueMarks(sources.Concat(new[]{new ScheduleSource{Name=name,Raw=raw,Catalog=a,Rows=a.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)}}));string label=a.Floor+" | "+name;string initial=label;int suffix=2;while(sources.Any(s=>s.Label==label))label=initial+" ("+suffix+++ ")";var source=new ScheduleSource{Label=label,Name=name,Raw=raw,Catalog=a,Rows=a.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)};filling=true;try{sources.Add(source);catalog=sources[0].Catalog;sourceText=sources[0].Raw;sourceName=string.Join("; ",sources.Select(s=>s.Name));var mark=(DataGridViewComboBoxColumn)beams.Columns[1];if(!mark.Items.Contains(""))mark.Items.Add("");foreach(var row in a.Source){schedules[row.Mark]=row;if(!mark.Items.Contains(row.Mark))mark.Items.Add(row.Mark);}((DataGridViewComboBoxColumn)beams.Columns[13]).Items.Add(label);foreach(DataGridViewRow entry in beams.Rows)if(!entry.IsNewRow)ConfigureMarkCell(entry);}finally{filling=false;}UpdateLoadedDxf();Recalculate();}
 internal void AddManual(BeamRow row){ManualBeamSchedule.Validate(row);if(schedules.ContainsKey(row.Mark))throw new Exception("Beam mark already exists: "+row.Mark);var existing=sources.FirstOrDefault(x=>x.Name==ManualBeamSchedule.FileName);var a=new Analysis();if(existing!=null)a.Source.AddRange(existing.Catalog.Source);a.Source.Add(row);string raw=ManualBeamSchedule.Serialize(a);if(existing==null){AppendCatalog(raw,ManualBeamSchedule.FileName);return;}existing.Raw=raw;existing.Catalog=ManualBeamSchedule.Read(raw,existing.Name);existing.Rows=existing.Catalog.Source.ToDictionary(x=>x.Mark,StringComparer.OrdinalIgnoreCase);schedules[row.Mark]=row;((DataGridViewComboBoxColumn)beams.Columns[1]).Items.Add(row.Mark);foreach(DataGridViewRow r in beams.Rows)if(!r.IsNewRow)ConfigureMarkCell(r);UpdateLoadedDxf();Recalculate();}
 void AddManualSchedule(){if(!Allowed())return;var row=ManualBeamSchedule.Choose(this);if(row!=null)AddManual(row);}
 internal List<EarthworkMaterial> WorksEarthworkMaterials(){var list=new List<EarthworkMaterial>();foreach(var i in inputs.Where(x=>x.Support!="Elevated"&&x.Earthworks!=null)){if(i.Earthworks==null)throw new Exception("Invalid beam earthworks: "+i.Beam);var e=i.Earthworks;list.Add(new EarthworkMaterial{Id=i.Beam+" "+i.Description,Source="Beam",Bank=e.Excavation,Fill=e.Backfill,Swell=e.Swell,Shrink=e.Shrink,Reusable=100});}return list;}
 internal double WorksGravel(){return inputs.Where(i=>i.Earthworks!=null).Sum(i=>i.Earthworks.Gravel);}
 internal object[,] EarthworkExcelRows(){var list=inputs.Where(i=>i.Earthworks!=null).ToList();var rows=new object[list.Count,18];for(int n=0;n<list.Count;n++){var i=list[n];var e=i.Earthworks;object[] v={i.Description,i.Beam,int.Parse(i.Quantity),e.Width,e.Depth,e.Allowance,e.Swell,e.Shrink,e.Excavation,e.Backfill,e.Gravel,e.LooseExcavation,e.LooseRequired,e.LooseSurplus,e.LooseImport,e.OtherConcrete,e.LooseFromExcavation,e.LooseImport};for(int c=0;c<v.Length;c++)rows[n,c]=v[c];}return rows;}
 internal void AppendEarthworksReport(StringBuilder b,bool detailed){var list=inputs.Where(i=>i.Support!="Elevated").ToList();if(list.Count==0)return;b.AppendLine();b.AppendLine("GROUND BEAM EARTHWORKS");foreach(var i in list){b.AppendLine(i.Description+" | "+i.Beam+" | Qty "+i.Quantity);if(i.Earthworks==null)b.AppendLine("  NOT MEASURED: "+i.EarthworkError);else i.Earthworks.Report(b,detailed);}var all=list.Where(i=>i.Earthworks!=null).Select(i=>i.Earthworks).ToList();b.AppendLine(string.Format(CultureInfo.InvariantCulture,"TOTAL: Excavation {0:0.00} bank m3 | Gravel {2:0.00} m3",all.Sum(x=>x.Excavation),all.Sum(x=>x.Backfill),all.Sum(x=>x.Gravel)));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"EMBANKMENT TOTAL: from excavation {0:0.00} | COMMON BORROW {1:0.00} loose m3",all.Sum(x=>x.LooseFromExcavation),all.Sum(x=>x.LooseImport)));b.AppendLine("Embankment quantities are LOOSE material before compaction. Common borrow is the quantity to obtain/deliver; no additional factor.");b.AppendLine("Soil balance is per entry; all excavated soil assumed reusable. No transfer between rows. Verify factors with soil report.");b.AppendLine("Rectangular trenches; no slopes, dewatering or shared-trench deductions. Count overlapping excavation only once.");if(list.Any(i=>i.Earthworks==null))b.AppendLine("PARTIAL EARTHWORKS: invalid rows excluded.");}
 void UpdateLoadedDxf(){sourceLabel.Text="Loaded DXF ("+sources.Count+"): "+string.Join("; ",sources.Select(s=>s.Name))+"\n"+sources.Sum(s=>s.Catalog.Source.Count)+" beam marks | Source is automatic from the selected beam mark.";help.SetToolTip(sourceLabel,string.Join("\n",sources.Select(s=>s.Name)));}
 void ManageSources(){if(!Allowed())return;beams.EndEdit();int index=DxfSourceManager.ChooseRemoval(this,sources.Select(s=>s.Name).ToArray(),sources.Select(s=>beams.Rows.Cast<DataGridViewRow>().Count(r=>!r.IsNewRow&&s.Rows.ContainsKey(Cell(r,1)))).ToArray());if(index<0)return;RemoveSourceAt(index);}
 internal void RemoveSourceAt(int index){if(index<0||index>=sources.Count)throw new ArgumentOutOfRangeException("index");var removed=sources[index];filling=true;try{foreach(var row in beams.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow&&removed.Rows.ContainsKey(Cell(r,1))).ToList())beams.Rows.Remove(row);sources.RemoveAt(index);schedules.Clear();var marks=(DataGridViewComboBoxColumn)beams.Columns[1];marks.Items.Clear();marks.Items.Add("");var labels=(DataGridViewComboBoxColumn)beams.Columns[13];labels.Items.Clear();foreach(var source in sources){labels.Items.Add(source.Label);foreach(var pair in source.Rows){schedules[pair.Key]=pair.Value;marks.Items.Add(pair.Key);}}catalog=sources.Count==0?null:sources[0].Catalog;sourceText=sources.Count==0?"":sources[0].Raw;sourceName=string.Join("; ",sources.Select(s=>s.Name));foreach(DataGridViewRow row in beams.Rows)if(!row.IsNewRow)ConfigureMarkCell(row);}finally{filling=false;}UpdateLoadedDxf();Recalculate();}
 static void CheckUniqueMarks(IEnumerable<ScheduleSource> candidates){var conflicts=candidates.GroupBy(s=>s.Raw).Select(g=>g.First()).SelectMany(s=>s.Rows.Keys.Select(mark=>new{Mark=mark,Source=s.Name})).GroupBy(x=>x.Mark,StringComparer.OrdinalIgnoreCase).Where(g=>g.Count()>1).Take(10).ToList();if(conflicts.Count>0)throw new Exception("Duplicate beam marks across DXF files. Use unique marks before loading:\n"+string.Join("\n",conflicts.Select(g=>g.Key+": "+string.Join(" / ",g.Select(x=>x.Source)))));}
 void ValidateFiles(List<string[]> files,bool append){var candidates=append?sources.ToList():new List<ScheduleSource>();foreach(var file in files){var parsed=ManualBeamSchedule.Read(file[0],file[1]);candidates.Add(new ScheduleSource{Name=file[1],Raw=file[0],Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}CheckUniqueMarks(candidates);}
 BeamRow FindSchedule(string label,string mark){BeamRow row;return schedules.TryGetValue(mark,out row)?row:null;}
 void ConfigureMarkCell(DataGridViewRow row){var cell=(DataGridViewComboBoxCell)row.Cells[1];cell.Items.Clear();cell.Items.Add("");cell.Items.AddRange(schedules.Keys.OrderBy(k=>k,StringComparer.OrdinalIgnoreCase).Cast<object>().ToArray());} public int AddEntry(string description="",string mark="",string length="",string quantity="",string schedule=""){if(!Allowed())return -1;if(sources.Count==0)throw new Exception("Load a revised schedule DXF first.");if(schedule=="")schedule=sources[0].Label;int index=beams.Rows.Add(description,mark.ToUpperInvariant(),"","",length,quantity,"","","","","","","",schedule);beams.Rows[index].Cells[14].Value="Elevated";beams.Rows[index].Cells[15].Value="0";ConfigureMarkCell(beams.Rows[index]);beams.CurrentCell=beams.Rows[index].Cells[0];Recalculate();return index;}
 public string[] ScheduleLabels(){return sources.Select(s=>s.Label).ToArray();} void RemoveSelected(){if(!Allowed())return;foreach(var row in beams.SelectedCells.Cast<DataGridViewCell>().Select(c=>c.OwningRow).Distinct().Where(r=>!r.IsNewRow).OrderByDescending(r=>r.Index).ToList())beams.Rows.Remove(row);Recalculate();}
 void ApplyBeamContext(DataGridViewRow row){row.Cells[14].Value=BeamSupportInput.Normalize(Cell(row,14));bool gravel=Cell(row,14)=="On Fill";foreach(string name in new[]{"ExcDepth","Swell","Shrink","OtherBuriedConcrete"}){row.Cells[name].ReadOnly=!gravel;row.Cells[name].Style.BackColor=gravel?ModernUi.Input:SystemColors.Control;}if(Cell(row,20)=="")row.Cells[20].Value=BeamEarthworks.DefaultSwellPercent.ToString("0.00",CultureInfo.InvariantCulture);row.Cells[19].Value=BeamEarthworks.WorkingSpacePerSide.ToString("0.00",CultureInfo.InvariantCulture);row.Cells[19].ReadOnly=true;row.Cells[19].Style.BackColor=SystemColors.Control;row.Cells[15].ReadOnly=true;row.Cells[15].Style.BackColor=gravel?SystemColors.Control:ModernUi.Input;row.Cells[15].ToolTipText=gravel?"Full beam depth is used for both side forms.":"Full beam depth is used for both side forms.";row.Cells[14].ToolTipText="Elevated: side and bottom forms. On Fill: side forms only; includes the entered trench/gravel quantities.";if(gravel)row.Cells[15].Value="0";}
 static string Cell(DataGridViewRow r,int c){return Convert.ToString(r.Cells[c].Value).Trim();}
 static double Read(string s,string field){double value;if(!double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value))throw new Exception("Invalid "+field+". Use a decimal number.");return value;}
 internal void SetProjectSoilFactors(double swell,double shrink){if(projectSwell==swell&&projectShrink==shrink)return;projectSwell=swell;projectShrink=shrink;beams.Columns[20].Visible=beams.Columns[21].Visible=false;Recalculate();}
 public void Recalculate(){if(filling)return;filling=true;try{inputs.Clear();EstimateOptions o=Options();string settingsError="";try{o.Validate();}catch(Exception e){settingsError=e.Message;}
  foreach(DataGridViewRow row in beams.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int c=2;c<4;c++)row.Cells[c].Value="";for(int c=8;c<=12;c++)row.Cells[c].Value="";string description=Cell(row,0),mark=Cell(row,1).ToUpperInvariant(),length=Cell(row,4);if(description==""&&mark==""&&length=="")continue;
   var owner=sources.FirstOrDefault(s=>s.Rows.ContainsKey(mark));row.Cells[13].Value=owner==null?"":owner.Label;ApplyBeamContext(row);if(projectSwell.HasValue){row.Cells[20].Value=projectSwell.Value.ToString(CultureInfo.InvariantCulture);row.Cells[21].Value=projectShrink.Value.ToString(CultureInfo.InvariantCulture);row.Cells[20].ReadOnly=row.Cells[21].ReadOnly=true;}var input=new EstimateInput{Description=description,ScheduleLabel=Cell(row,13),Beam=mark,Length=length,Quantity=Cell(row,5),TieCount="",TieCut="",ExcavationDepth=Cell(row,18),WorkingAllowance=BeamEarthworks.WorkingSpacePerSide.ToString("0.00",CultureInfo.InvariantCulture),Swell=Cell(row,20)==""?BeamEarthworks.DefaultSwellPercent.ToString("0.00",CultureInfo.InvariantCulture):Cell(row,20),Shrink=Cell(row,21)==""?"10":Cell(row,21),OtherBuriedConcrete=Cell(row,22)==""?"0":Cell(row,22),Support=Cell(row,14)==""?"Elevated":Cell(row,14),SlabThickness="0"};inputs.Add(input);row.Tag=input;row.Cells[16].Value=row.Cells[17].Value="";try{var geometry=FindSchedule(input.ScheduleLabel,mark);if(geometry==null)throw new Exception("Choose a beam mark");input.Measures=BeamQuantities.Calculate(Read(geometry.Cell(0),"width"),Read(geometry.Cell(1),"depth"),Read(length,"length"),int.Parse(input.Quantity),input.Support!="Elevated",Read(input.SlabThickness,"slab thickness"));row.Cells[16].Value=input.Measures.Concrete.ToString("N2");row.Cells[17].Value=input.Measures.Formwork.ToString("N2");}catch(Exception ex){input.MeasureError=ex.Message;}
   for(int n=23;n<=31;n++)row.Cells[n].Value="";
   if(input.Support=="On Fill")try{var g=FindSchedule(input.ScheduleLabel,mark);if(g==null)throw new Exception("Choose a beam mark");double d=Read(g.Cell(1),"D")/1000;var earth=BeamEarthworks.Calculate(Read(g.Cell(0),"B")/1000,d,Read(length,"length"),int.Parse(input.Quantity),input.ExcavationDepth==""?d+.10:Read(input.ExcavationDepth,"excavation depth"),Read(input.WorkingAllowance,"side allowance"),Read(input.Swell,"swell"),Read(input.Shrink,"shrinkage"),Read(input.OtherBuriedConcrete,"other buried concrete"));input.Earthworks=earth;row.Cells[30].Value=earth.LooseFromExcavation.ToString("N2");row.Cells[31].Value=earth.LooseImport.ToString("N2");double[] v={earth.Excavation,earth.Backfill,earth.LooseExcavation,earth.LooseRequired,earth.LooseSurplus,earth.LooseImport};for(int n=0;n<v.Length;n++)row.Cells[23+n].Value=v[n].ToString("N2");row.Cells[29].Value="Estimated | verify soil factors";if(input.ExcavationDepth=="")row.Cells[18].ToolTipText="Automatic depth now: "+earth.Depth.ToString("0.00")+"m (D + 0.10m). Type an override or leave blank.";}catch(Exception ex){input.EarthworkError=ex.Message;row.Cells[29].Value=ex.Message;}
   try{if(settingsError!="")throw new Exception(settingsError);if(description=="")throw new Exception("Enter a description");BeamRow schedule=FindSchedule(input.ScheduleLabel,mark);if(schedule==null)throw new Exception("Choose a beam mark from the revised DXF");input.Source=schedule;row.Cells[2].Value=schedule.Cell(0);row.Cells[3].Value=schedule.Cell(1);if(length=="")throw new Exception("Enter length in metres");int q;if(!int.TryParse(input.Quantity,out q)||q<=0||q>100000)throw new Exception("Quantity must be 1 to 100000 whole beams");int? count=null;if(input.TieCount!=""){int n;if(!int.TryParse(input.TieCount,out n))throw new Exception("Tie sets must be a whole number");count=n;}double? cut=input.TieCut==""?(double?)null:Read(input.TieCut,"tie cut m/set");input.Result=EstimatorEngine.Calculate(schedule,mark,Read(length,"beam length"),o);foreach(var line in input.Result.Lines){if(q>1)line.Formula+=" PER BEAM x "+q+" beams";line.Metres*=q;line.Kg*=q;}input.Result.Ties=checked(input.Result.Ties*q);row.Cells[8].Value=input.Result.LongKg.ToString("N2");row.Cells[9].Value=input.Result.TieKg.ToString("N2");row.Cells[10].Value=input.Result.SfrKg.ToString("N2");row.Cells[11].Value=(input.Result.Total*(1+o.Waste/100)).ToString("N2");row.Cells[12].Value="Estimated | "+input.Result.Ties+" tie sets total";
   }catch(Exception e){input.Result=null;input.Error=e.Message;row.Cells[12].Value=e.Message;}
  }
  totals.Rows.Clear();var lines=inputs.Where(i=>i.Result!=null).SelectMany(i=>i.Result.Lines).ToList();foreach(var g in lines.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double kg=g.Sum(l=>l.Kg);totals.Rows.Add("\u00D8"+g.Key,kg.ToString("N2"),(kg*o.Waste/100).ToString("N2"),(kg*(1+o.Waste/100)).ToString("N2"));}gradeTotals.Rows.Clear();foreach(int steel in new[]{40,60}){var byGrade=lines.Where(l=>l.Grade==steel).ToList();foreach(var g in byGrade.GroupBy(l=>l.Diameter).OrderBy(g=>g.Key)){double kg=g.Sum(l=>l.Kg);gradeTotals.Rows.Add("G"+steel,"D"+g.Key,kg.ToString("N2"),(kg*o.Waste/100).ToString("N2"),(kg*(1+o.Waste/100)).ToString("N2"));}double subtotal=byGrade.Sum(l=>l.Kg);int r=gradeTotals.Rows.Add("G"+steel+" TOTAL","",subtotal.ToString("N2"),(subtotal*o.Waste/100).ToString("N2"),(subtotal*(1+o.Waste/100)).ToString("N2"));gradeTotals.Rows[r].DefaultCellStyle.BackColor=Color.FromArgb(220,233,247);}int done=inputs.Count(i=>i.Result!=null),quantity=inputs.Where(i=>i.Result!=null).Sum(i=>int.Parse(i.Quantity));status.Text=done+" / "+inputs.Count+" entries estimated | "+quantity+" beams | "+(done<inputs.Count?"PARTIAL TOTAL: ":"TOTAL: ")+(lines.Sum(l=>l.Kg)*(1+o.Waste/100)).ToString("N2")+" kg";
  UpdatePurchaseTotals();
 }finally{filling=false;var changed=WorksChanged;if(changed!=null)changed(this,EventArgs.Empty);}ShowSelected();if(excelLink!=null){excelTimer.Stop();excelTimer.Start();}}
 void ShowSelected(){if(details==null||beams.CurrentRow==null||beams.CurrentRow.IsNewRow)return;var row=beams.CurrentRow;string desc=Cell(row,0),mark=Cell(row,1).ToUpperInvariant();var b=new StringBuilder();b.AppendLine(desc+" | "+mark+" | L="+Cell(row,4)+"m | Qty="+Cell(row,5));BeamRow schedule=FindSchedule(Cell(row,13),mark);if(schedule!=null){b.AppendLine("FLOOR / SOURCE: "+Cell(row,13));b.AppendLine("REVISED SCHEDULE: "+schedule.Cell(0)+" x "+schedule.Cell(1)+"mm");for(int c=0;c<3;c++)b.AppendLine(new[]{"LEFT   ","MIDSPAN","RIGHT  "}[c]+" bottom: "+string.Join(" + ",schedule.Cells[2+c])+" | top: "+string.Join(" + ",schedule.Cells[5+c]));b.AppendLine("Stirrups: "+schedule.Leg+" / "+schedule.Diameter+" / "+schedule.RevisedSpacing);b.AppendLine("SFR: "+schedule.Cell(11));}b.AppendLine("STATUS: "+Cell(row,12));var input=row.Tag as EstimateInput;if(input!=null&&input.Result!=null){foreach(var l in input.Result.Lines)b.AppendLine(EstimatorEngine.DisplayPart(l.Part)+" \u00D8"+l.Diameter+": "+l.Formula+" = "+l.Kg.ToString("0.00")+"kg");foreach(var n in input.Result.Notes)b.AppendLine("NOTE: "+n);}if(input!=null&&input.Earthworks!=null)input.Earthworks.Report(b,true);else if(input!=null&&input.EarthworkError!="")b.AppendLine("EARTHWORK ERROR: "+input.EarthworkError);details.Text=b.ToString().Replace("%%C","\u00D8").Replace("%%c","\u00D8");}
 string State(){return reportMode.SelectedIndex+"|"+CommercialBars.FormatLengths(stockLengths)+"|"+string.Join("\n",sources.Select(s=>s.Label+s.Raw))+Options().Description()+(lengthProfile==null?"":ProfileState())+string.Join("\n",inputs.Select(i=>i.ScheduleLabel+"|"+i.Description+"|"+i.Beam+"|"+i.Length+"|"+i.Quantity+"|"+i.TieCount+"|"+i.TieCut+"|"+i.Support+"|"+i.SlabThickness+"|"+i.ExcavationDepth+"|"+i.WorkingAllowance+"|"+i.Swell+"|"+i.Shrink+"|"+i.OtherBuriedConcrete));}
 void UpdatePurchaseTotals(){var plan=CommercialBars.Allocate(inputs,lengthProfile,stockLengths);foreach(DataGridViewRow row in beams.Rows){var i=row.Tag as EstimateInput;if(i==null||i.Result==null)continue;var item=plan.Where(a=>a.Entry==i).ToList();if(item.Any(a=>a.Choice==null)){for(int c=8;c<=11;c++)row.Cells[c].Value="REVIEW";row.Cells[12].Value="Unresolved commercial cut; purchase excluded";continue;}row.Cells[8].Value=item.Where(a=>a.Line.Part!="Stirrups"&&a.Line.Part!="Side-face").Sum(a=>a.Purchase).ToString("N2");row.Cells[9].Value=item.Where(a=>a.Line.Part=="Stirrups").Sum(a=>a.Purchase).ToString("N2");row.Cells[10].Value=item.Where(a=>a.Line.Part=="Side-face").Sum(a=>a.Purchase).ToString("N2");row.Cells[11].Value=item.Sum(a=>a.Purchase).ToString("N2");}
  beams.Columns[8].HeaderText="MAIN BUY kg";beams.Columns[9].HeaderText="TIES BUY kg";beams.Columns[10].HeaderText="SFR BUY kg";beams.Columns[11].HeaderText="TOTAL BUY kg";
  totals.Columns[2].HeaderText="LAP+OFFCUT kg";totals.Columns[3].HeaderText="BUY kg";gradeTotals.Columns[3].HeaderText="LAP+OFFCUT kg";gradeTotals.Columns[4].HeaderText="BUY kg";totals.Rows.Clear();gradeTotals.Rows.Clear();foreach(var g in plan.GroupBy(a=>a.Demand.Diameter).OrderBy(g=>g.Key))totals.Rows.Add("D"+g.Key,g.Sum(a=>a.Net).ToString("N2"),g.Sum(a=>a.Splice+a.Waste).ToString("N2"),g.Sum(a=>a.Purchase).ToString("N2"));foreach(int grade in new[]{40,60}){var steel=plan.Where(a=>a.Demand.Grade==grade).ToList();foreach(var g in steel.GroupBy(a=>a.Demand.Diameter).OrderBy(g=>g.Key))gradeTotals.Rows.Add("G"+grade,"D"+g.Key,g.Sum(a=>a.Net).ToString("N2"),g.Sum(a=>a.Splice+a.Waste).ToString("N2"),g.Sum(a=>a.Purchase).ToString("N2"));gradeTotals.Rows.Add("G"+grade+" TOTAL","",steel.Sum(a=>a.Net).ToString("N2"),steel.Sum(a=>a.Splice+a.Waste).ToString("N2"),steel.Sum(a=>a.Purchase).ToString("N2"));}status.Text=(plan.Any(a=>a.Choice==null)||inputs.Any(i=>i.Result==null)?"PARTIAL / REVIEW | ":"")+"TOTAL TO BUY: "+plan.Sum(a=>a.Purchase).ToString("N2")+" kg | shared stock/offcuts allocated by used length";
 }
 public string Report(){beams.EndEdit();Recalculate();var plan=CommercialBars.Allocate(inputs,lengthProfile,stockLengths);var b=new StringBuilder();int mode=reportMode.SelectedIndex;b.AppendLine("REINFORCING STEEL BARS | PURCHASE BACKUP");b.AppendLine(new string('-',92));b.AppendLine("Report: "+reportMode.Text+" | "+DateTime.Now.ToString("yyyy-MM-dd HH:mm"));b.AppendLine("Available commercial lengths: "+CommercialBars.FormatLengths(stockLengths)+" m");if(mode==2){b.AppendLine("Nominal masses: project-supplied table, kg/m.");b.AppendLine("Compatible different-length cuts share stock and offcuts; grades/diameters stay separate. Kerf=0.");}if(plan.Any(a=>a.Choice==null)||inputs.Any(i=>i.Result==null))b.AppendLine("PARTIAL: unresolved cuts / invalid entries require review; excluded from purchase.");b.AppendLine();AppendConcreteReport(b);AppendEarthworksReport(b,mode>0);b.AppendLine();AppendPurchaseSummary(b,plan);b.AppendLine();b.AppendLine("02  BACKUP QUANTITIES BY DESCRIPTION");b.AppendLine(new string('-',92));for(int n=0;n<inputs.Count;n++){var i=inputs[n];var item=plan.Where(a=>a.Entry==i).ToList();b.AppendLine((n+1).ToString("00")+"  "+i.Description+" | "+i.Beam+" | B="+(i.Source==null?"?":i.Source.Cell(0))+" D="+(i.Source==null?"?":i.Source.Cell(1))+" mm | L="+i.Length+"m | Qty="+i.Quantity);if(i.Result==null){b.AppendLine("   NOT ESTIMATED: "+i.Error);continue;}if(mode==0)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"   BUY: Main {0:0.00} | Ties {1:0.00} | SFR {2:0.00} | TOTAL {3:0.00} kg",item.Where(a=>a.Line.Part!="Stirrups"&&a.Line.Part!="Side-face").Sum(a=>a.Purchase),item.Where(a=>a.Line.Part=="Stirrups").Sum(a=>a.Purchase),item.Where(a=>a.Line.Part=="Side-face").Sum(a=>a.Purchase),item.Sum(a=>a.Purchase)));if(item.Any(a=>a.Choice==null))b.AppendLine("   PARTIAL: unresolved cut demand.");if(mode>0){b.AppendLine();PurchaseReports.Entry(b,item,int.Parse(i.Quantity),mode==2);}b.AppendLine();}
  b.AppendLine(new string('-',92));b.AppendLine("TOTAL REBAR TO PURCHASE: "+plan.Sum(a=>a.Purchase).ToString("0.00",CultureInfo.InvariantCulture)+" kg");PurchaseReports.Basis(b);if(mode==2){b.AppendLine();b.AppendLine(CommercialBars.Report(inputs,lengthProfile,stockLengths));}return b.ToString();
 }
 void AppendConcreteReport(StringBuilder b){b.AppendLine("CONCRETE & FORMWORK SUMMARY");b.AppendLine("Side forms = 2 x full beam depth x length x quantity. Elevated beams add soffit; ground/gravel beams have no soffit forms. No slab thickness deduction.");b.AppendLine(string.Format("{0,-24}{1,-16}{2,8}{3,15}{4,15}","DESCRIPTION / MARK","SUPPORT","QTY","CONCRETE m3","FORMWORK m2"));foreach(var i in inputs){if(i.Measures==null){b.AppendLine(i.Description+" / "+i.Beam+": NOT MEASURED - "+i.MeasureError);continue;}b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-24}{1,-16}{2,8}{3,15:0.00}{4,15:0.00}",(i.Description+" / "+i.Beam).Length>23?(i.Description+" / "+i.Beam).Substring(0,23):i.Description+" / "+i.Beam,i.Support,i.Quantity,i.Measures.Concrete,i.Measures.Formwork));}b.AppendLine(string.Format(CultureInfo.InvariantCulture,"TOTAL CONCRETE: {0:0.00} m3 | TOTAL FORMWORK: {1:0.00} m2",inputs.Where(i=>i.Measures!=null).Sum(i=>i.Measures.Concrete),inputs.Where(i=>i.Measures!=null).Sum(i=>i.Measures.Formwork)));if(inputs.Any(i=>i.Measures==null))b.AppendLine("PARTIAL concrete/formwork takeoff: invalid geometry excluded.");b.AppendLine();}
 public object[,] ConcreteExcelRows(){var items=inputs.Where(i=>i.Measures!=null).ToList();var rows=new object[items.Count,8];for(int n=0;n<items.Count;n++){var i=items[n];rows[n,0]=i.Description;rows[n,1]=i.Beam;rows[n,2]=i.Support;rows[n,3]=int.Parse(i.Quantity);rows[n,4]=i.Measures.Concrete;rows[n,5]=i.Measures.SideForms;rows[n,6]=i.Measures.BottomForms;rows[n,7]=i.Measures.Formwork;}return rows;}
 static string PurchasePart(StockAllocation a){if(a.Line.Part=="Side-face")return "SFR / EACH FACE";if(a.Line.Part=="Stirrups")return a.Line.TieOverride?"STIRRUP MANUAL SET":Math.Abs(a.Demand.Cut-a.Line.MainHoopCut)<1e-9?"MAIN STIRRUP / HOOP":"ADDITIONAL LEG (90+130)";return EstimatorEngine.DisplayPart(a.Line.Part);}
 internal static void AppendPurchaseSummary(StringBuilder b,List<StockAllocation> plan){PurchaseReports.Summary(b,plan);}
 static void AppendTieBreakdown(StringBuilder b,EstimateInput input,int quantity){b.AppendLine("STIRRUP CUT LENGTHS & QUANTITIES");b.AppendLine(string.Format("{0,-30}{1,7}{2,10}{3,13}{4,14}","TYPE","DIA","PCS/BEAM","CUT m/pc","TOTAL m"));foreach(var line in input.Result.Lines.Where(l=>l.Part=="Stirrups")){int sets=line.TieSetsPerBeam>0?line.TieSetsPerBeam:input.Result.Ties/quantity;Action<string,double,int> row=(name,cut,pcs)=>{double metres=cut*pcs*quantity;b.AppendLine(string.Format(CultureInfo.InvariantCulture,"{0,-30}{1,7}{2,10}{3,13:0.00}{4,14:0.00}",name,line.Diameter,pcs,cut,metres));};if(line.TieOverride){row("Manual combined set",line.CutLength,sets);b.AppendLine("Manual cut override: component split is not available.");continue;}row("Main stirrup / hoop",line.MainHoopCut,sets);row("Additional leg (90+130)",line.AdditionalLegs==0?0:line.AdditionalLegCut,sets*line.AdditionalLegs);}} void ExportPdf(){if(!Allowed())return;beams.EndEdit();Recalculate();if(!inputs.Any(i=>i.Result!=null))throw new Exception("Add at least one valid estimate entry.");using(var d=new SaveFileDialog{Filter="Printable PDF (*.pdf)|*.pdf",FileName="Beam-Estimate-Backup.pdf"})if(d.ShowDialog(this)==DialogResult.OK){EngineeringQuantityPdf.WriteFlattened(d.FileName,BuildEngineeringReport());MessageBox.Show("Saved the selected RSB purchase report.\n"+d.FileName);}}
 string EstimateXml(){if(catalog==null)throw new Exception("Load a revised DXF first.");var doc=new XmlDocument();var root=doc.CreateElement("BeamEstimate");root.SetAttribute("version","6");root.SetAttribute("reportMode",reportMode.SelectedIndex.ToString());root.SetAttribute("stockLengths",CommercialBars.FormatLengths(stockLengths));root.SetAttribute("sourceName",sourceName);doc.AppendChild(root);var sourceList=doc.CreateElement("ScheduleSources");root.AppendChild(sourceList);foreach(var item in sources){var source=doc.CreateElement("Source");source.SetAttribute("label",item.Label);source.SetAttribute("name",item.Name);source.InnerText=item.Raw;sourceList.AppendChild(source);}var settings=doc.CreateElement("Settings");var o=Options();double[] vals={o.GradeSmall,o.Grade,o.Fc,o.MainHook,o.Anchorage,o.BondRatio,o.Left,o.Right,o.Cover,o.Hook,o.Extra,o.Waste,o.Offset};string[] names={"gradeSmall","grade","fc","mainHook","anchorage","bond","left","right","cover","hook","extra","waste","offset"};for(int n=0;n<names.Length;n++)settings.SetAttribute(names[n],vals[n].ToString("R",CultureInfo.InvariantCulture));root.AppendChild(settings);if(lengthProfile!=null){var configuration=doc.CreateElement("LengthConfiguration");lengthProfile.Write(configuration);root.AppendChild(configuration);}foreach(var i in inputs){var e=doc.CreateElement("Entry");e.SetAttribute("schedule",i.ScheduleLabel);e.SetAttribute("description",i.Description);e.SetAttribute("mark",i.Beam);e.SetAttribute("length",i.Length);e.SetAttribute("quantity",i.Quantity);e.SetAttribute("tieCount",i.TieCount);e.SetAttribute("tieCut",i.TieCut);e.SetAttribute("support",i.Support);e.SetAttribute("slabThickness",i.SlabThickness);e.SetAttribute("excavationDepth",i.ExcavationDepth);e.SetAttribute("workingAllowance",i.WorkingAllowance);e.SetAttribute("swell",i.Swell);e.SetAttribute("shrink",i.Shrink);e.SetAttribute("otherBuriedConcrete",i.OtherBuriedConcrete);root.AppendChild(e);}return doc.OuterXml;}
