 internal object[,] WorksExcelRows(List<StockAllocation> shared=null,bool requireValid=true){if(requireValid&&inputs.Any(i=>i.Result==null||i.Measures==null||(i.Support!="Elevated"&&i.Earthworks==null)))throw new Exception("Resolve invalid beam entries before syncing Program of Works.");return ExcelRows(shared,requireValid);}
 public event EventHandler WorksChanged;
