 public void SaveTo(string path){beams.EndEdit();Recalculate();var doc=new XmlDocument{XmlResolver=null};doc.LoadXml(EstimateXml());string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);File.Copy(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}savedState=State();}
 public void OpenFrom(string path){OpenEstimateXml(File.ReadAllText(path));}
 void OpenEstimateXml(string xml){var doc=new XmlDocument{XmlResolver=null};using(var text=new StringReader(xml))using(var reader=XmlReader.Create(text,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=100000000}))doc.Load(reader);var root=doc.DocumentElement;if(root==null||root.Name!="BeamEstimate"||!new[]{"3","4","5","6"}.Contains(root.GetAttribute("version")))throw new Exception("Use a revised-DXF estimate project from v1.4.1 or later.");var checkedSources=new List<ScheduleSource>();if(root["ScheduleSources"]!=null){foreach(XmlElement element in root.SelectNodes("ScheduleSources/Source")){var parsed=ManualBeamSchedule.Read(element.InnerText,element.GetAttribute("name"));checkedSources.Add(new ScheduleSource{Label=element.GetAttribute("label"),Name=element.GetAttribute("name"),Raw=element.InnerText,Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}}else{string raw=root["ScheduleDxf"].InnerText,name=root.GetAttribute("sourceName");var parsed=ManualBeamSchedule.Read(raw,name);checkedSources.Add(new ScheduleSource{Label=parsed.Floor+" | "+name,Name=name,Raw=raw,Catalog=parsed,Rows=parsed.Source.ToDictionary(r=>r.Mark,StringComparer.OrdinalIgnoreCase)});}if(checkedSources.Count==0||checkedSources.Select(s=>s.Label).Distinct().Count()!=checkedSources.Count)throw new Exception("Invalid or duplicate floor/source identifiers.");CheckUniqueMarks(checkedSources);foreach(XmlElement entry in root.SelectNodes("Entry")){string label=entry.HasAttribute("schedule")?entry.GetAttribute("schedule"):checkedSources[0].Label;var source=checkedSources.FirstOrDefault(s=>s.Label==label);if(source==null||(entry.GetAttribute("mark")!=""&&!source.Rows.ContainsKey(entry.GetAttribute("mark"))))throw new Exception("Project entry has a missing floor/source or beam mark.");}stockLengths=CommercialBars.ParseLengths(root.GetAttribute("stockLengths"));reportMode.SelectedIndex=root.HasAttribute("reportMode")?Math.Max(0,Math.Min(2,int.Parse(root.GetAttribute("reportMode")))):0;LoadCatalog(checkedSources[0].Raw,checkedSources[0].Name);sources[0].Label=checkedSources[0].Label;((DataGridViewComboBoxColumn)beams.Columns[13]).Items[0]=sources[0].Label;foreach(var source in checkedSources.Skip(1)){AppendCatalog(source.Raw,source.Name);sources[sources.Count-1].Label=source.Label;((DataGridViewComboBoxColumn)beams.Columns[13]).Items[sources.Count-1]=source.Label;}ApplyLengthConfiguration(root["LengthConfiguration"]==null?null:LengthConfiguration.Read(root["LengthConfiguration"]));filling=true;try{var e=root["Settings"];if(root["LengthConfiguration"]==null){gradeSmall.SelectedIndex=e.GetAttribute("gradeSmall")=="60"?1:0;grade.SelectedIndex=e.GetAttribute("grade")=="40"?1:0;SetConcrete(Read(e.GetAttribute("fc"),"fc"));lengthProfile=CalculationStore.Resolve((double)concrete.SelectedItem,((SteelSelection)gradeSmall.SelectedItem).Grade,((SteelSelection)gradeSmall.SelectedItem).Fy,((SteelSelection)grade.SelectedItem).Grade,((SteelSelection)grade.SelectedItem).Fy);}mainHook.SelectedIndex=e.GetAttribute("mainHook")=="180"?2:e.GetAttribute("mainHook")=="90"?1:0;anchorage.SelectedIndex=(int)Read(e.GetAttribute("anchorage"),"anchorage");NumericUpDown[] controls={bond,cover,hook,extra,waste};string[] names={"bond","cover","hook","extra","waste"};for(int n=0;n<names.Length;n++)controls[n].Value=(decimal)Read(e.GetAttribute(names[n]),names[n])*(names[n]=="left"||names[n]=="right"?100:1);CheckUniqueMarks(checkedSources);foreach(XmlElement entry in root.SelectNodes("Entry")){string label=entry.HasAttribute("schedule")?entry.GetAttribute("schedule"):sources[0].Label;int r=beams.Rows.Add(entry.GetAttribute("description"),entry.GetAttribute("mark"),"","",entry.GetAttribute("length"),entry.GetAttribute("quantity"),entry.GetAttribute("tieCount"),entry.GetAttribute("tieCut"),"","","","","",label);beams.Rows[r].Cells[14].Value=BeamSupportInput.Normalize(entry.GetAttribute("support"));beams.Rows[r].Cells[15].Value=entry.HasAttribute("slabThickness")?entry.GetAttribute("slabThickness"):"0";foreach(var pair in new[]{new[]{"18","excavationDepth"},new[]{"19","workingAllowance"},new[]{"20","swell"},new[]{"21","shrink"},new[]{"22","otherBuriedConcrete"}})beams.Rows[r].Cells[int.Parse(pair[0])].Value=entry.GetAttribute(pair[1]);ConfigureMarkCell(beams.Rows[r]);}}finally{filling=false;}UpdateConfigurationLabel();Recalculate();savedState=State();} string ProfileState(){var d=new XmlDocument();var e=d.CreateElement("Configuration");lengthProfile.Write(e);return e.OuterXml;}
 public Control WorksSettings {get;private set;}
 internal List<double> WorksStockLengths {get{return new List<double>(stockLengths);}}
